// Worker1OL only (192.168.56.10). The "application down / connection refused"
// scenario has been split out into its own dedicated workflow
// (itsm_nexacore_down_incident_generator_workflow.json) so it can be
// scheduled/toggled independently of this 404 scenario -- this workflow now
// generates ONLY the 404 case. Matches KB0000034 (static-file-serving 404
// fix) and is phrased to match how this incident actually reads historically
// in the DB so RAG retrieval matches the same way it does for a real
// human-filed ticket.
const incidentList = [
  {
    text: "Nexacore Application is throwing 404 error. Getting below error. HTTP 404 Not Found - The requested resource (index.html) could not be found on this server. URL: http://worker1ol:9000/",
    targetCi: "Worker1OL",
    priority: "P2",
    impact: "DEPARTMENT",
    urgency: "HIGH"
  }
];

const index = Math.floor(Date.now() / (5 * 60 * 1000)) % incidentList.length;
const selected = incidentList[index];

return [{
  json: {
    shortDescription: selected.text,
    description: selected.text,
    configurationItem: selected.targetCi,
    priority: selected.priority,
    impact: selected.impact,
    urgency: selected.urgency,
    callerName: "n8n Telemetry Engine",
    generatedAt: new Date().toISOString()
  }
}];

const res = $input.first().json;
const body = res.body || res;

return [{
  json: {
    status: 'SUCCESS',
    incidentNumber: body.number || body.id,
    title: body.shortDescription,
    configurationItem: body.configurationItem || body.configurationItemName,
    priority: body.priority,
    state: body.state,
    createdAt: body.createdAt || new Date().toISOString(),
    message: `[n8n] Successfully created ${body.priority} incident ${body.number || body.id}: "${body.shortDescription}" on ${body.configurationItem || body.configurationItemName}`
  }
}];
